<template><div data-ui-id="weekly-grid" class="weekly-grid" role="grid"><template v-for="(day,di) in rows" :key="day.date||di"><span class="day-label">{{day.date?.slice(5)||'—'}}</span><button v-for="(value,hi) in hours(day)" :key="`${di}-${hi}`" class="heat-cell" :class="level(value,peak)" :title="`${day.date||'日期未知'} ${String(hi).padStart(2,'0')}:00 · ${value??'—'}`" @click="$emit('select',`${day.date}-${hi}`)"/></template></div></template>
<script setup>const p=defineProps({days:Array,peak:Number});defineEmits(['select']);const rows=p.days||[];const hours=d=>Array.from({length:24},(_,i)=>d?.hours?.[i]??null);const level=(v,peak)=>v==null?'missing':!v?'l0':`l${Math.min(5,Math.ceil((v/(peak||1))*5))}`</script>
